class AsyncQueue {
  #items = []; #waiters = [];
  async push(item) { this.#items.push(item); this.#waiters.shift()?.(); }
  async *drain() {
    while (true) {
      while (!this.#items.length) await new Promise(resolve => this.#waiters.push(resolve));
      yield this.#items.shift();
    }
  }
}
